if (!VALID_SIZES.has(settlementSize)) throw new Error(`Invalid settlementSize: ${settlementSize}`);
if (!description) throw new Error('Missing required field: description');
return [{ json: { name, storeType, level, settlementSize, description, _prepSuccess: true } }];

// Parse & Assemble Store (PF2e) — normalize the LLM payload into a safe store object
function safeParse(raw) {
  if (!raw) return null;
  if (typeof raw === 'object') return raw;
  try { let s = String(raw).trim(); if (s.startsWith('```')) s = s.replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, ''); return JSON.parse(s); } catch { return null; }
}
const prepInput = $('Prep Store Input').first().json;
const { name, storeType, level, settlementSize, description } = prepInput;
const raw = $json.message?.content ?? $json.completion ?? $json.text ?? null;
const parsed = safeParse(raw);

const VALID_TYPES = new Set(['weapon','armor','shield','equipment','consumable','treasure','backpack','book']);
const VALID_RARITY = new Set(['common','uncommon','rare','unique']);
const VALID_DAMAGE = new Set(['bludgeoning','piercing','slashing','bleed','acid','cold','electricity','fire','sonic','force','vitality','void','mental','poison','spirit','untyped']);
const DAMAGE_REMAP = { positive:'vitality', negative:'void', necrotic:'void', radiant:'vitality', good:'spirit', evil:'spirit', lawful:'spirit', chaotic:'spirit', thunder:'sonic', lightning:'electricity', psychic:'mental', physical:'bludgeoning', magic:'force' };
function toInt(v, fb = 0) { const n = Number(v); return Number.isFinite(n) ? Math.trunc(n) : fb; }
function clamp(n, lo, hi) { return Math.min(hi, Math.max(lo, n)); }

const warnings = [];
if (!parsed) warnings.push('LLM output unparseable');
const base = parsed && typeof parsed === 'object' ? parsed : {};
const owner = (base.owner && typeof base.owner === 'object') ? base.owner : (base.shopkeeper && typeof base.shopkeeper === 'object') ? base.shopkeeper : null;

const rawInventory = Array.isArray(base.inventory) ? base.inventory : Array.isArray(base.items) ? base.items : [];
const MAX_ITEMS = 14;
const inventory = [];
for (const rawItem of rawInventory.slice(0, MAX_ITEMS)) {
  if (!rawItem || typeof rawItem !== 'object') continue;
  const sys = (rawItem.system && typeof rawItem.system === 'object') ? rawItem.system : {};
  const type = VALID_TYPES.has(String(rawItem.type||'').toLowerCase()) ? String(rawItem.type).toLowerCase() : 'equipment';
  const item = { name: String(rawItem.name || 'Unnamed Item').slice(0, 120), type, img: String(rawItem.img || 'icons/svg/item-bag.svg'), system: sys };
  const s = item.system;
  const rawDesc = s.description?.value ?? s.description ?? '';
  s.description = { value: typeof rawDesc === 'string' ? rawDesc : String(rawDesc || '') };
  s.level = { value: clamp(toInt(s.level?.value ?? s.level, 0), 0, 25) };
  const rawTraits = Array.isArray(s.traits?.value) ? s.traits.value : (Array.isArray(s.traits) ? s.traits : []);
  const rarityRaw = String(s.traits?.rarity || 'common').toLowerCase();
  s.traits = { value: rawTraits.map(t => String(t).toLowerCase().trim().replace(/\s+/g,'-')).filter(Boolean), rarity: VALID_RARITY.has(rarityRaw) ? rarityRaw : 'common', otherTags: [] };
  const rawPrice = s.price?.value ?? s.price ?? {};
  const price = {};
  for (const k of ['pp','gp','sp','cp']) { const v = toInt(rawPrice[k], 0); if (v > 0) price[k] = v; }
  s.price = { value: price };
  let bulkVal = s.bulk?.value ?? s.bulk ?? 0;
  if (typeof bulkVal === 'string') { const lower = bulkVal.trim().toLowerCase(); bulkVal = (lower === 'l' || lower === 'light') ? 0.1 : (parseFloat(lower) || 0); }
  s.bulk = { value: Math.max(0, Number(bulkVal) || 0) };
  s.quantity = Math.max(1, toInt(s.quantity, 1));
  s.size = 'med';
  s.publication = { title: 'JamesCfer', license: 'ORC', remaster: true };
  if (type === 'weapon' && s.damage && typeof s.damage === 'object') {
    const dt = String(s.damage.damageType || 'slashing').toLowerCase();
    s.damage.damageType = VALID_DAMAGE.has(dt) ? dt : (DAMAGE_REMAP[dt] || 'slashing');
    s.damage.dice = clamp(toInt(s.damage.dice, 1), 1, 4);
    s.damage.modifier = toInt(s.damage.modifier, 0);
  }
  if (type === 'consumable' && !s.traits.value.includes('consumable')) s.traits.value.push('consumable');
  inventory.push(item);
}

const store = {
  name: String(base.name || name || 'Generated Store').slice(0, 120),
  storeType,
  settlementSize,
  description: String(base.description || description || '').slice(0, 4000),
  owner: owner ? { name: String(owner.name || 'Shopkeeper').slice(0, 120), ancestry: String(owner.ancestry || owner.race || '').slice(0, 60), description: String(owner.description || '').slice(0, 2000) } : null,
