console.log('[Assemble Store] "' + store.name + '" ' + storeType + '/' + settlementSize + ' items=' + inventory.length + ' warnings=' + warnings.length);
return [{ json: { ...prepInput, store, _warnings: warnings, _assembled: true } }];

