const store = upstream.store || {};
const targetCount = $('Build Store Prompt').first().json._targetCount || 8;
const issues = [];
if (upstream._warnings && upstream._warnings.includes('LLM output unparseable')) issues.push('Prior output was not valid JSON. Return strictly valid JSON this time.');
const inv = Array.isArray(store.inventory) ? store.inventory : [];
if (inv.length < Math.ceil(targetCount * 0.6)) issues.push('Inventory has only ' + inv.length + ' items but the request asked for ' + targetCount + '. Provide the full inventory.');
if (!store.owner || !store.owner.name || store.owner.name === 'Shopkeeper') issues.push('Missing shopkeeper: provide owner with a proper name and a 2-3 sentence description.');
if (!store.description || store.description.length < 60) issues.push('Store description is missing or too short. Provide 1-2 flavourful paragraphs.');
const FORBIDDEN = ["gm's discretion", "gms discretion", "at the gm's option", "the gm may decide", "an unspecified benefit", "an unspecified bonus", "as appropriate"];
const allText = (String(store.description||'') + ' ' + inv.map(i => String(i.system?.description?.value||'')).join(' ')).toLowerCase();
for (const phrase of FORBIDDEN) if (allText.includes(phrase)) issues.push('Text contains forbidden phrase: "' + phrase + '"');
const unnamed = inv.filter(i => !i.name || i.name === 'Unnamed Item').length;
if (unnamed > 0) issues.push(unnamed + ' inventory item(s) are missing names.');
const noDesc = inv.filter(i => !i.system?.description?.value).length;
if (noDesc > Math.ceil(inv.length / 3)) issues.push(noDesc + ' inventory item(s) have empty descriptions. Every item needs at least one sentence.');
const passed = issues.length === 0;
console.log('[Audit Store] "' + (store.name || 'unknown') + '" audit=' + (passed ? 'PASS' : 'FAIL') + ' issues=' + issues.length);
for (const i of issues) console.log('  - ' + i);
return [{ json: { ...upstream, _auditPassed: passed, _auditIssues: issues } }];

