const { name, storeType, level, settlementSize, description } = prep;
const upstream = $json;
const store = upstream.store || {};
const issues = upstream._auditIssues || [];
const priorSummary = JSON.stringify({ name: store.name, owner: store.owner, description: (store.description||'').slice(0,300), inventory: (store.inventory||[]).map(i => ({ name: i.name, type: i.type, level: i.system?.level?.value, price: i.system?.price?.value })) }, null, 2);
const issueList = issues.map((v, i) => (i + 1) + '. ' + v).join('
');
const SYSTEM_PROMPT = 'You are a PF2e Foundry VTT store designer performing a CORRECTION PASS.

You previously generated a store that failed automated checks. Produce a CORRECTED version that:
1. Keeps the same store name, type, theme, and shopkeeper (unless an issue says otherwise).
2. Fixes every issue listed below.
3. Returns STRICT JSON only with the exact same top-level shape as before: { name, storeType, settlementSize, description, owner: { name, ancestry, description }, inventory: [complete Foundry PF2e item objects] }.

Key rules: every item has name/type/img/system with description, level, traits (magical items include "magical"), price { value: { gp } }, bulk, quantity, size "med", publication.title "JamesCfer". Remaster damage types only. No GM-discretion language.

Return ONLY the corrected JSON object.';
const USER_PROMPT = 'ORIGINAL REQUEST:
- Store name: ' + name + '
- Store type: ' + storeType + '
- Typical stock level: ' + level + '
- Settlement: ' + settlementSize + '
- Description: ' + description + '

YOUR PRIOR OUTPUT (abbreviated):
' + priorSummary + '

ISSUES TO FIX (fix ALL):
' + issueList + '

Produce the corrected full store JSON, including COMPLETE item objects for the whole inventory. Return ONLY the JSON.';
return [{ json: { ...upstream, system: SYSTEM_PROMPT, user: USER_PROMPT } }];

